from typing import Protocol


class Repository(Protocol):
    def save(self, item): ...
    def load(self, key): ...


class Clock(Protocol):
    def now(self): ...

from core.ports import Repository, Clock


class Service:
    def __init__(self, repo: Repository, clock: Clock):
        self.repo = repo
        self.clock = clock

    def run(self, item):
        self.repo.save(item)


def build(repo: Repository):
    return Service(repo, None)

import sqlite3
from core.ports import Repository


class SqlRepository(Repository):
    def __init__(self, path):
        self.conn = sqlite3.connect(path)

    def save(self, item):
        self.conn.execute("INSERT INTO items VALUES (?)", (item,))

    def load(self, key):
        return self.conn.execute("SELECT * FROM items WHERE k = ?", (key,))

